def formula(moneyness, implied_volatility):
    T = 1.0
    return np.clip(0.5 + moneyness / (2 * implied_volatility * np.sqrt(T)), 0, 1)

def formula(spot_price, implied_volatility, time_to_expiry):
    d1 = (np.log(spot_price / spot_price) + 0.5 * implied_volatility**2 * time_to_expiry) / (implied_volatility * np.sqrt(time_to_expiry))
    return np.exp(-0.5 * d1**2) / (np.sqrt(2 * np.pi)) / (spot_price * implied_volatility * np.sqrt(time_to_expiry))

def formula(spot_price, implied_volatility, time_to_expiry):
    d1 = (np.log(spot_price / spot_price) + 0.5 * implied_volatility**2 * time_to_expiry) / (implied_volatility * np.sqrt(time_to_expiry))
    N_prime_d1 = (1 / np.sqrt(2 * np.pi)) * np.exp(-0.5 * d1**2)
    return spot_price * N_prime_d1 * np.sqrt(time_to_expiry)

def formula(entry_price, leverage):
    maintenance_margin = 0.8
    return entry_price * (1 - 1 / (leverage * maintenance_margin))
